"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RadioGroup, RadioGroupItem } from "@atlas/ui-web/primitives/RadioGroup/RadioGroup"
import { ROLES, type OnboardingStepProps, type Role } from "../schema"

const column = { display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" } as const
const errorText = {
  margin: 0,
  color: "var(--atlas-danger)",
  fontSize: "var(--atlas-text-body-sm)",
} as const

function validateName(name: string): string | null {
  const trimmed = name.trim()
  if (!trimmed) return "Enter your full name."
  if (trimmed.length < 2) return "Full name must be at least 2 characters."
  return null
}

export function Profile({ data, patch, next }: OnboardingStepProps) {
  const [submitted, setSubmitted] = useState(false)
  const nameError = submitted ? validateName(data.fullName) : null
  const roleError = submitted && !data.role ? "Choose the role that fits you best." : null

  const submit = () => {
    setSubmitted(true)
    if (validateName(data.fullName) || !data.role) return
    next()
  }

  return (
    <form
      noValidate
      onSubmit={(e) => { e.preventDefault(); submit() }}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-6)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
      }}
    >
      <header style={column}>
        <h1 style={{ margin: 0, fontSize: "var(--atlas-text-h1)", fontWeight: "var(--atlas-font-weight-bold)", color: "var(--atlas-foreground)" }}>
          Tell us about you
        </h1>
        <p style={{ margin: 0, color: "var(--atlas-foreground-muted)", fontSize: "var(--atlas-text-body)" }}>
          We use this to personalise your workspace.
        </p>
      </header>

      <div style={column}>
        <Label htmlFor="onb-name" required invalid={!!nameError}>Full name</Label>
        <Input
          id="onb-name"
          size="lg"
          autoComplete="name"
          value={data.fullName}
          invalid={!!nameError}
          aria-required="true"
          aria-describedby={nameError ? "onb-name-err" : undefined}
          onChange={(e) => patch({ fullName: e.target.value })}
        />
        {nameError && <p id="onb-name-err" role="alert" style={errorText}>{nameError}</p>}
      </div>

      <div style={column}>
        <Label id="onb-role-label" required invalid={!!roleError}>Role</Label>
        <RadioGroup
          aria-labelledby="onb-role-label"
          aria-describedby={roleError ? "onb-role-err" : undefined}
          variant="card"
          value={data.role}
          required
          invalid={!!roleError}
          onValueChange={(v) => patch({ role: v as Role })}
        >
          {ROLES.map((r) => (
            <RadioGroupItem key={r.value} value={r.value} label={r.label} variant="card" invalid={!!roleError} />
          ))}
        </RadioGroup>
        {roleError && <p id="onb-role-err" role="alert" style={errorText}>{roleError}</p>}
      </div>

      <Button type="submit" variant="primary" size="lg">Continue</Button>
    </form>
  )
}

