"use client"
import { useRouter } from "next/navigation"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { PLANS, type OnboardingStepProps } from "../schema"

export function Done({ data, back }: OnboardingStepProps) {
  const router = useRouter()
  const plan = PLANS.find((p) => p.value === data.plan)?.label ?? data.plan
  const firstName = data.fullName.trim().split(/\s+/)[0]

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-6)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
      }}
    >
      <Alert
        variant="success"
        size="lg"
        title={`You're all set, ${firstName}`}
        description={`Your account is ready on the ${plan} plan.`}
      />
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <Button variant="primary" size="lg" onClick={() => router.push("/prototypes")}>Continue to app</Button>
        <Button variant="outline" size="lg" onClick={back}>Back</Button>
      </div>
    </div>
  )
}

